const fireEffects=createFireEffects(scene);const fireControls=createFireControls(fireSimulation,{log,isEnded:()=>ended});const flashControls=addFlashoverControls(fireSimulation,{log,isEnded:()=>ended,isRunning:()=>running});let fireUiTime=0;
