const vehicleView=document.createElement('button');vehicleView.textContent='查看車輛';document.querySelector('.viewcontrols').append(vehicleView);vehicleView.onclick=()=>{following=false;focusButton.classList.remove('active');focusButton.textContent='跟隨車組';const v=vehicleModels[selected].root.position;controls.target.copy(v).add(new THREE.Vector3(0,1.3,0));camera.position.copy(v).add(selected===3?new THREE.Vector3(-5,3.8,6):new THREE.Vector3(5,3.8,-6));document.querySelectorAll('[data-view]').forEach(b=>b.classList.remove('active'));};
