rankView.onclick=()=>{following=false;focusButton.classList.remove('active');focusButton.textContent='跟隨車組';const p=actionScene.roleExamples[rankIndex++%4];p.body.updateWorldMatrix(true,false);const v=p.body.getWorldPosition(new THREE.Vector3()),q=p.body.getWorldQuaternion(new THREE.Quaternion());controls.target.copy(v).add(new THREE.Vector3(0,1.1,0));camera.position.copy(v).add(new THREE.Vector3(2.1,1.9,-3).applyQuaternion(q));rankView.textContent='人員近看：'+p.rank;document.querySelectorAll('[data-view]').forEach(b=>b.classList.remove('active'));};
patientController=createPatients(scene,{log,isEnded:()=>ended,focus:p=>{if(commanderControl.active)commanderControl.leave();view('section');controls.target.set(...p);camera.position.set(p[0]+9,p[1]+6,p[2]+12)}});
const commanderControl=createCommanderControl({scene,camera,controls,renderer,commander:actionScene.commander,excluded:[aerial.importedVisual,aerial.truck.root,patientController.root,...vehicleModels.map(v=>v.visual).filter(Boolean),navigationMarkers,...actionScene.actors.map(a=>a.root),...aerial.crew.map(p=>p.body),aerial.basket,...aerial.booms,aerial.civilian],onEnter:()=>{navigationMarkers.visible=false;following=false;facade.visible=true;roof.visible=true;focusButton.classList.remove('active');focusButton.textContent='跟隨車組';},onExit:()=>{navigationMarkers.visible=true;}});
const resize=new ResizeObserver(()=>{const w=container.clientWidth,h=container.clientHeight;camera.aspect=w/h;camera.fov=commanderControl.active?70:w<650?58:42;camera.updateProjectionMatrix();renderer.setSize(w,h)});resize.observe(container);function view(type){navigationMarkers.visible=type!=='section';following=false;focusButton.classList.remove('active');focusButton.textContent='跟隨車組';facade.visible=type!=='section';roof.visible=type!=='section';camera.position.set(...(type==='rear'?[20,17,-26]:type==='street'?[20,7,28]:type==='section'?[22,23,30]:[31,27,35]));controls.target.set(0,type==='street'?6:4,0);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===type))}const rearButton=document.createElement('button');rearButton.dataset.view='rear';rearButton.textContent='建物後側';document.querySelector('.viewcontrols').append(rearButton);document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$('home').onclick=()=>view('overview');const ray=new THREE.Raycaster(),pointer=new THREE.Vector2();let down;renderer.domElement.addEventListener('pointerdown',e=>down=[e.clientX,e.clientY]);renderer.domElement.addEventListener('pointerup',e=>{if(commanderControl.active)return;if(!down||Math.hypot(e.clientX-down[0],e.clientY-down[1])>5)return;const r=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);const hit=ray.intersectObjects(pickables)[0];if(hit){$('location').value=hit.object.userData.location;$('feedback').textContent='已選擇位置：'+locationNames[$('location').value]}});
let last=0,visualTime=0;function animate(time){const dt=Math.min((time-last)/1000,.1);last=time;if(running)stepFire(fireSimulation,dt,{vent:ventilation,water:effectiveWater(units)});fireUiTime+=dt;if(fireUiTime>.2){fireControls.update();flashControls.update();patientController?.update();fireUiTime=0}if(running||!started)visualTime+=dt;fireEffects.update(visualTime,seconds,!facade.visible,fireSimulation,dt);actionScene.update(dt,visualTime,units,running,selected,searchReport);if(commanderControl.active)actionScene.actors.forEach(a=>a.ring.visible=false);aerial.update(dt,running);aerial.updateImported?.(dt);if(aerial.nativePose?.blocked)$('aerialAccept').disabled=true;refreshMissionButtons();refreshCageControls();updateAerialCalculations();beacons.forEach((b,i)=>{b.material.emissiveIntensity=Math.sin(visualTime*10+(b.userData.flashPhase??i*3))>0?4:.1});if(following){const target=actionScene.actors[selected].root.position.clone().add(new THREE.Vector3(0,1,0));controls.target.lerp(target,.08);camera.position.lerp(target.clone().add(new THREE.Vector3(7,5,9)),.035)}if(commanderControl.active)commanderControl.update(dt);else controls.update();renderer.render(scene,camera);requestAnimationFrame(animate)}requestAnimationFrame(animate);
